{
  "title": "Cache JSON-RPC client responses",
  "description": "A developer frequently calls the same JSON-RPC methods and wants to avoid redundant network traffic. They need a wrapper around `HttpClient` that caches successful responses for a configurable TTL.",
  "code_context": "use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, SystemTime};
use serde_json::Value;
use jsonrpc_utils::HttpClient;

pub struct RpcCache {
    inner: Mutex<HashMap<String, (Value, SystemTime)>>,
    ttl: Duration,
}

impl RpcCache {
    pub fn new(ttl: Duration) -> Self {
        Self {
            inner: Mutex::new(HashMap::new()),
            ttl,
        }
    }

    pub fn get(&self, method: &str, params: &Value) -> Option<Value> {
        let key = format!("{}-{:?}", method, params);
        let mut guard = self.inner.lock().unwrap();
        if let Some((value, ts)) = guard.get(&key) {
            if SystemTime::now().duration_since(*ts).ok()? < self.ttl {
                return Some(value.clone());
            }
        }
        None
    }

    pub fn set(&self, method: &str, params: &Value, value: &Value) {
        let key = format!("{}-{:?}", method, params);
        let mut guard = self.inner.lock().unwrap();
        guard.insert(key, (value.clone(), SystemTime::now()));
    }
}

pub struct CachingHttpClient {
    inner: HttpClient,
    cache: Arc<RpcCache>,
}

impl CachingHttpClient {
    pub fn new(inner: HttpClient, cache: Arc<RpcCache>) -> Self {
        Self { inner, cache }
    }
}",
  "function_signature": "fn rpc(&self, method: &str, params: &serde_json::Value) -> anyhow::Result<serde_json::Value>"
}

