  "description": "A developer needs to replace every occurrence of a pattern in the active file. The helper fetches the file content from the global State, performs the replacement, updates the EditArea, and marks the file as edited.",
  "code_context": "use cursive::Cursive;
use crate::error::Error;
use crate::error::Result;
use crate::app::State;
use crate::ui::edit_area::EditArea;

pub fn replace_in_current_file(siv: &mut Cursive, from: &str, to: &str) -> Result<()> {
    let mut state = siv.with_user_data(|state: &mut State| state.clone()).ok_or_else(|| Error::Arguments("No state".into()))?;
    let current_path = state.current_file.as_ref().ok_or_else(|| Error::Arguments("No file selected".into()))?.clone();
    let file_data = state.get_file(&current_path).ok_or_else(|| Error::FileSystem("File not in state".into()))?;
    let new_content = file_data.str.replace(from, to);
    siv.call_on_name("editor", |edit_area: &mut EditArea| {
        edit_area.set_content(new_content.clone());
    })?;
    if let Some(mut data) = state.files.get_mut(&current_path) {
        data.str = new_content;
        state.files_edited.insert(current_path.clone(), true);
    }
    siv.set_user_data(state);
    Ok(())
}",
